from .common import *
def wheels(items,zs,width=1.83,r=.42):
 for j,z in enumerate(zs):
  for sg in [-1,1]:items.append(pi('wheel'+str(j)+('L' if sg<0 else 'R'),'core.vehicle.wheel',[sg*width*.5,r,z],params={'radius':r,'width':.24 if r>.35 else .20}))
 return items

